<?php
defined('ABSPATH') || exit;

if (!function_exists('nub20_pool')) {
    function nub20_pool(): array {
        static $pool = null;
        if (is_array($pool)) return $pool;
        $pool = function_exists('wc_get_products') ? wc_get_products([
            'status' => 'publish', 'limit' => 40, 'orderby' => 'date', 'order' => 'DESC', 'return' => 'objects',
        ]) : [];
        return is_array($pool) ? array_values($pool) : [];
    }
    function nub20_pick(int $count, int $offset = 0): array {
        $pool = nub20_pool(); $total = count($pool); $out = [];
        if (!$total) return $out;
        for ($i = 0; $i < $count; $i++) $out[] = $pool[($offset + $i) % $total];
        return $out;
    }
    function nub20_img($product, string $size = 'woocommerce_thumbnail'): string {
        return $product instanceof WC_Product
            ? $product->get_image($size, ['loading' => 'lazy', 'alt' => $product->get_name()])
            : '<span class="n20-fallback">NUB</span>';
    }
    function nub20_shop(): string {
        return function_exists('wc_get_page_permalink') ? wc_get_page_permalink('shop') : home_url('/shop/');
    }
    function nub20_page(string $slug, string $fallback = ''): string {
        $page = get_page_by_path($slug);
        return $page instanceof WP_Post ? get_permalink($page) : ($fallback ?: home_url('/' . trim($slug, '/') . '/'));
    }
    function nub20_card($product, bool $small = false): void {
        if (!$product instanceof WC_Product) return;
        $simple = $product->is_type('simple') && $product->is_purchasable() && $product->is_in_stock();
        $url = $simple ? $product->add_to_cart_url() : $product->get_permalink();
        $classes = $simple ? 'n20-add add_to_cart_button ajax_add_to_cart product_type_simple' : 'n20-add';
        echo '<article class="n20-card' . ($small ? ' small' : '') . '">';
        echo '<a class="n20-media" href="' . esc_url($product->get_permalink()) . '">';
        echo '<button class="n20-heart" type="button" aria-label="Wishlist">♡</button>';
        if ($product->is_on_sale()) echo '<span class="n20-sale">Sale</span>';
        echo wp_kses_post(nub20_img($product));
        echo '</a><div class="n20-card-copy"><h3><a href="' . esc_url($product->get_permalink()) . '">' . esc_html($product->get_name()) . '</a></h3>';
        echo '<p>Dermatologist-inspired formula</p><div class="n20-meta"><strong>' . wp_kses_post($product->get_price_html()) . '</strong><span>★ ' . esc_html($product->get_average_rating() ?: 'New') . '</span></div>';
        echo '<a class="' . esc_attr($classes) . '" href="' . esc_url($url) . '" data-product_id="' . esc_attr((string)$product->get_id()) . '" data-quantity="1" rel="nofollow">' . ($simple ? '+ Add to Cart' : 'View Product') . '</a></div></article>';
    }
}

get_header();

$shop = nub20_shop();
$cart = function_exists('wc_get_cart_url') ? wc_get_cart_url() : nub20_page('cart');
$account = function_exists('wc_get_page_permalink') ? wc_get_page_permalink('myaccount') : nub20_page('my-account');
$all = nub20_pick(10);
$hero = $all[0] ?? null;
$categories = ['Cleansers','Serums','Moisturizers','Sunscreen','Masks','Body Care'];
$today = nub20_pick(10, 0);
$weekly = nub20_pick(5, 2);
$most = nub20_pick(5, 4);
$just = nub20_pick(5, 1);
$count = function_exists('WC') && WC()->cart ? WC()->cart->get_cart_contents_count() : 0;
?>
